long p99(List<Long> latencesMs) {
    // 1) copier puis trier par ordre croissant
    // 2) indice = ceil(0.99 * taille) - 1, borné à 0
    // 3) renvoyer la valeur à cet indice
}

solution:
long p99(List<Long> latencesMs) {
    List<Long> tri = new ArrayList<>(latencesMs);
    Collections.sort(tri);
    int index = (int) Math.ceil(0.99 * tri.size()) - 1;
    if (index < 0) index = 0;
    return tri.get(index);
}
